"""Run exact original CLI once in fresh mirror root; never overwrite frozen evidence."""
from pathlib import Path
from itertools import combinations
import ast,hashlib,json,platform,shutil,subprocess,sys,time
E=Path(__file__).resolve().parent;rows=json.loads((E/'source-manifest.json').read_text());programrow=next(x for x in rows if x['path'].endswith('.py'));replay=E/'replay';replay.mkdir(exist_ok=False);root=replay/'source-root';root.mkdir();program=root/programrow['path'];program.parent.mkdir(parents=True);shutil.copyfile(E/'original'/programrow['path'],program)
output=replay/'current-original-output.json';assert not output.exists();argv=[sys.executable,str(program),'--output',str(output)]
# These are the source's complete built-in finite inputs, made explicit without executing source functions.
catalogues=[{'n':n,'catalogue_masks':list(c)}for n in range(5)for size in range(1,min(3,1<<n)+1)for c in combinations(range(1<<n),size)]
(replay/'complete-built-input-catalogues.json').write_text(json.dumps(catalogues,ensure_ascii=False,indent=2)+'\n')
(replay/'input-domain.json').write_text(json.dumps({'source':'all input constructed in original main; no external file read','n':list(range(5)),'mask_meaning':'bit x means topic covers unit customer x','catalogues':'all distinct mask subsets of size1..min(3,2**n), explicitly enumerated in complete-built-input-catalogues.json','catalogue_count':len(catalogues),'m':[1,2,3],'T':'all combinations_with_replacement(catalogue,m) maximizing union cardinality; one canonical sorted order per multiset, no T permutations','B':'all ordered product(catalogue,repeat=m)','bernoulli_p':['0','1/3','1/2','2/3','1'],'realizations':'only when m<=2 and p=1/2, enumerate all2**m replacement bit words with uniform1/2**m weights','harmonic':'exact finite Fraction H_c','alpha':[1,2,3],'matching':'closed hypergeometric coefficient; no explicit m! permutation loop','anchor':'each same-position index j where optimum[j]==profile[j], including empty theme; fixed theme protected, formula uses m-1 residual slots','spe_calls':0,'external_file_inputs':[]},ensure_ascii=False,indent=2)+'\n')
start=time.time();proc=subprocess.run(argv,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.PIPE);duration=time.time()-start
(replay/'original.stdout.txt').write_bytes(proc.stdout);(replay/'original.stderr.txt').write_bytes(proc.stderr)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
state={'original_program_calls':1,'execution_count':1,'argv':argv,'cwd':str(root),'python':sys.version,'executable':sys.executable,'optimize':sys.flags.optimize,'platform':platform.platform(),'program':programrow['path'],'program_bytes':program.stat().st_size,'program_sha256':sha(program),'exit_code':proc.returncode,'duration_seconds':duration,'stdout_bytes':len(proc.stdout),'stderr_bytes':len(proc.stderr),'stdout_sha256':sha(replay/'original.stdout.txt'),'stderr_sha256':sha(replay/'original.stderr.txt'),'report_created':output.exists(),'external_dependencies':[],'local_program_imports':[],'source_output_behavior':'summary-only stdout by default; explicit --output opens new file in x mode, parent mkdir allowed; CLI supplied only new independent report path','path_difference':'original repo-relative source path inside new external source-root, not original frozen physical root','input_catalogue_count':len(catalogues),'no_source_function_instrumentation':True}
if output.exists():
 state.update({'new_report_bytes':output.stat().st_size,'new_report_sha256':sha(output),'json_stdout_equals_report':json.loads(proc.stdout)==json.loads(output.read_text()),'matches_frozen_reports':[x['id']for x in rows if x['path'].endswith('.json')and output.read_bytes()==(E/'original'/x['path']).read_bytes()]})
(replay/'execution-state.json').write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n');print(json.dumps(state,ensure_ascii=False));assert proc.returncode==0,'Failure retained; no automatic retry'
